tool_input.command:
python3 - <<'EOF'
import pathlib
p = pathlib.Path("<repo>/.tmp/rehash.go")
t = p.read_text()
anchor = '''	// JSON-escaped renderings: patterns as they appear inside raw JSONL'''
add = '''	// Regex-escaped-punctuation renderings (backslash before every
	// non-alphanumeric), as recorded from grep/sed pattern arguments.
	escPunct := func(s string) string {
		var b strings.Builder
		for _, r := range s {
			if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9') {
				b.WriteByte('\\\\')
			}
			b.WriteRune(r)
		}
		return b.String()
	}
	var withPunct [][2]string
	for _, pr := range pairs {
		withPunct = append(withPunct, pr)
		if e := escPunct(pr[0]); e != pr[0] {
			withPunct = append(withPunct, [2]string{e, pr[1]})
		}
	}
	pairs = withPunct
	var spPunct []string
	for _, s := range scanPatterns {
		spPunct = append(spPunct, s)
		if e := escPunct(s); e != s {
			spPunct = append(spPunct, e)
		}
	}
	scanPatterns = spPunct
	// JSON-escaped renderings: patterns as they appear inside raw JSONL'''
assert anchor in t
t = t.replace(anchor, add, 1)
p.write_text(t)
print("punct-escape variants added")
EOF
